def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(out),len(out[0])
    # Continue diagonals indicated by adjacent equal-colored cells, from the forward endpoint.
    original=[r[:] for r in grid]
    for r in range(h):
      for c in range(w):
        color=original[r][c]
        if color in (0,4): continue
        for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
          pr,pc=r-dr,c-dc
          if 0<=pr<h and 0<=pc<w and original[pr][pc]==color:
            nr,nc=r+dr,c+dc
            while 0<=nr<h and 0<=nc<w:
              out[nr][nc]=color
              nr+=dr; nc+=dc
    return out
